INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36911, 'Luke 1:65', 'Luke', 1, 65, 'ټول ګاونډیان ووېرېدل او د یهودیې په ټوله غرنۍ سیمه کې خلکو د دې شیانو په هکله خبرې کولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_65.mp3', '', 1761754199, 1761754199),
(36912, 'Luke 1:66', 'Luke', 1, 66, 'هرچا چې دا خبره اورېدله، نو د هغې په هکله یې فکر کاوه او پوښتنه یې کوله: «د دې ماشوم څخه به څه جوړ شي؟» ځکه چې د څښتن لاس د هغه په سر باندې ؤ. د زکریا پېشګويي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_66.mp3', '', 1761754199, 1761754199),
(36913, 'Luke 1:67', 'Luke', 1, 67, 'د یحیی پلار زکریا د روح القدس نه ډک شو او د خدای پیغام یې ورکړ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_67.mp3', '', 1761754199, 1761754199),
(36914, 'Luke 1:68', 'Luke', 1, 68, '«ثنا او صفت دې وي څښتن ته چې دی خدای د اسراییلو ځکه راغی چې وکړي مرسته د خپل قوم سره چې کړي ازاد هغوی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_68.mp3', '', 1761754199, 1761754199),
(36915, 'Luke 1:69', 'Luke', 1, 69, 'هغه پیدا کړ مونږ ته زورور ژغورونکی د اولادې نه د داود چې خدمتګار یې ؤ خپل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_69.mp3', '', 1761754199, 1761754199),
(36916, 'Luke 1:70', 'Luke', 1, 70, 'لکه څنګه چې پخوا یې وو ویلي په خوله د سپېڅلو پخوانیو پیغمبرانو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_70.mp3', '', 1761754199, 1761754199),
(36917, 'Luke 1:71', 'Luke', 1, 71, 'چې مو خلاص کړي د خپلو دښمنانو ځینې د هغو خلکو څخه چې کوي کرکه له مونږ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_71.mp3', '', 1761754199, 1761754199),
(36918, 'Luke 1:72', 'Luke', 1, 72, 'رحم به وکړي هغه زمونږ نیکونو باندې او رایادوي به خپل سپېڅلی لوظ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_72.mp3', '', 1761754199, 1761754199),
(36919, 'Luke 1:73', 'Luke', 1, 73, 'هغه قسم چې ؤ خوړلی هغه زمونږ د نیکه ابراهیمه سره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_73.mp3', '', 1761754199, 1761754199),
(36920, 'Luke 1:74', 'Luke', 1, 74, 'چې به کړي خلاص هغه مونږ له دښمنانو ځینې چې بې له وېرې وکړو مونږه خدمت د هغه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_74.mp3', '', 1761754199, 1761754199),
(36921, 'Luke 1:75', 'Luke', 1, 75, 'په ټول ژوندون کې د پاکۍ او عدالت سره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_75.mp3', '', 1761754199, 1761754199),
(36922, 'Luke 1:76', 'Luke', 1, 76, 'او ای ماشومه زما ته به یادېږې پیغمبر د خدای تعالی ځکه چې ځې به له څښتنه مخکې چې کړې تیاره لاره ته د هغه دپاره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_76.mp3', '', 1761754199, 1761754199),
(36923, 'Luke 1:77', 'Luke', 1, 77, 'چې په دې پوه کړې قوم د هغه چې دوی به ومومي خلاصون د خپلو ګناهونو په بخښلو سره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_77.mp3', '', 1761754199, 1761754199),
(36924, 'Luke 1:78', 'Luke', 1, 78, 'زمونږ د خدای د رحم او مهربانۍ په سبب په مونږ را وبه خېژي لمر د سهار پاس له اسمانه څخه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_78.mp3', '', 1761754199, 1761754199),
(36925, 'Luke 1:79', 'Luke', 1, 79, 'ترڅو چې راولي رڼا په هغو خلکو باندې چې تېروي ژوند په تیارو کې د مرګ او برابر کړي قدمونه زمونږ د سولې او سلامتۍ په لاره»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_79.mp3', '', 1761754199, 1761754199),
(36926, 'Luke 1:80', 'Luke', 1, 80, 'هغه ماشوم غټېده او په روحاني توګه قوي کېده او تر هغه وخته پورې په دښته کې اوسېده، ترڅو د اسراییلو خلکو ته په څرګنده توګه ورښکاره شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke1_verse_80.mp3', '', 1761754199, 1761754199),
(36927, 'Revelation 9:1', 'Revelation', 9, 1, 'بیا پنځمې فرښتې خپل سرنی وواهه او ما یو ستوری ولیده چې د اسمان نه ځمکې ته راولوېد او هغه ستوري ته د ځمکې د تل د لارې کیلي ورکړل شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_1.mp3', '', 1761754199, 1761754199),
(36928, 'Revelation 9:2', 'Revelation', 9, 2, 'هغه په دې کیلي باندې د ځمکې د تل لاره خلاصه کړه او د هغې کندې نه د یو لوی داش د لوګي په شان لوګی راپورته شو او لمر او هوا د هغه داش د لوګي له امله تیاره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_2.mp3', '', 1761754199, 1761754199),
(36929, 'Revelation 9:3', 'Revelation', 9, 3, 'بیا د لوګي نه ځمکې ته ملخان راووتل او هغوی ته لکه د لړمانو په شان قدرت ورکړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_3.mp3', '', 1761754199, 1761754199),
(36930, 'Revelation 9:4', 'Revelation', 9, 4, 'هغوی ته وویل شول چې واښو، ونو او بوټو ته زیان ونه رسوي، بلکې یوازې هغو خلکو ته زیان ورسوي چې د هغو په تندیو باندې د خدای مهر نه وي لګېدلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_4.mp3', '', 1761754199, 1761754199),
(36931, 'Revelation 9:5', 'Revelation', 9, 5, 'ملخانو ته اجازه ورکړل شوه چې هغه خلکو ته پنځه میاشتې عذاب ورکړي، داسې عذاب چې د لړم د چیچلو په شان وي، خو د هغوی د وژلو اجازه ورته نه وه ورکړل شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_5.mp3', '', 1761754199, 1761754199),
(36932, 'Revelation 9:6', 'Revelation', 9, 6, 'په هغو ورځو کې به دغه کسان مرګ وغواړي خو مرګ به ورته نه راځي. هغوی به د مرګ په ارمان وي، خو مرګ به ورڅخه تښتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_6.mp3', '', 1761754199, 1761754199),
(36933, 'Revelation 9:7', 'Revelation', 9, 7, 'دا ملخان د هغو اسونو په شان ښکاره کېدل چې جنګ ته تیار وي. د هغوی په سرونو باندې د سرو زرو په شان تاجونه وو او مخونه یې د انسان د مخونو په شان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_7.mp3', '', 1761754199, 1761754199),
(36934, 'Revelation 9:8', 'Revelation', 9, 8, 'د هغوی ویښتان د ښځو د ویښتانو په شان وو او غاښونه یې د زمریو د غاښونو په شان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_8.mp3', '', 1761754199, 1761754199),
(36935, 'Revelation 9:9', 'Revelation', 9, 9, 'هغوی لکه د اوسپنې څخه جوړ شویو زغرو کالي اغوستې وو او د هغوی د وزرونو اواز د اسونو او ډېرو جنګي ګاډیو د غړمبار په شان ؤ چې د جنګ میدان ته ځغلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_9.mp3', '', 1761754199, 1761754199),
(36936, 'Revelation 9:10', 'Revelation', 9, 10, 'د هغوی لکۍ‌ګانو لکه د لړمانو د لکیو په شان نېشونه لرل چې د دې قدرت یې درلود چې په خپلو لکۍ‌ګانو سره پنځه میاشتې خلک وځوروي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_10.mp3', '', 1761754199, 1761754199),
(36937, 'Revelation 9:11', 'Revelation', 9, 11, 'د هغوی پاچا یوه فرښته وه چې د ځمکې د تل د کندې مشره وه چې په عبراني ژبه کې د هغې نوم ابدون او په یوناني ژبه کې آپولیون ؤ چې معنی یې تباه کوونکې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_11.mp3', '', 1761754199, 1761754199),
(36938, 'Revelation 9:12', 'Revelation', 9, 12, 'یوه بلا تېره شوه او دوه نورې شته چې راتلونکې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_12.mp3', '', 1761754199, 1761754199),
(36939, 'Revelation 9:13', 'Revelation', 9, 13, 'بیا شپږمې فرښتې خپل سرنی وواهه او یو اواز مې واورېد چې د سرو زرو د قربانۍ د ځای د څلورو کونجونو څخه چې د خدای په حضور کې ؤ، راووت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_13.mp3', '', 1761754199, 1761754199),
(36940, 'Revelation 9:14', 'Revelation', 9, 14, 'هغه اواز شپږمې فرښتې ته چې سرنی ورسره ؤ، وویل: «د لوی فرات د سیند نه هغه څلور تړل شوې فرښتې ازادې کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_14.mp3', '', 1761754199, 1761754199),
(36941, 'Revelation 9:15', 'Revelation', 9, 15, 'نو هغه څلور فرښتې ازادې شوې چې د درېمې برخې انسانانو د وژلو دپاره د دې کال، د دې میاشتې، د دې ورځې او د دې ساعت دپاره تیارې کړای شوې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_15.mp3', '', 1761754199, 1761754199),
(36942, 'Revelation 9:16', 'Revelation', 9, 16, 'ما د سپرو لښکرو شمېر واورېد چې دوه سوه میلیونه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_16.mp3', '', 1761754199, 1761754199),
(36943, 'Revelation 9:17', 'Revelation', 9, 17, 'ما په رویا کې اسونه او په هغو باندې سپاره کسان ولیدل. سپرو کسانو د اور په شان سرې، اسماني رنګه او د ګوګړو په شان زیړې زغرې اغوستې وې. د اسونو سرونه یې د زمریو د سرونو په شان وو او د خولې نه یې اور، لوګی او د ګوګړو لمبې راوتلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_17.mp3', '', 1761754199, 1761754199),
(36944, 'Revelation 9:18', 'Revelation', 9, 18, 'د دې درېو بلاګانو یعنې اور، لوګي او ګوګړو په وسیله چې د هغوی د خولې نه راوتل، درېمه برخه انسانان مړه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_18.mp3', '', 1761754199, 1761754199),
(36945, 'Revelation 9:19', 'Revelation', 9, 19, 'ځکه چې د اسونو قوت د هغوی په خولو او لکۍ‌ګانو کې ؤ. د هغوی لکۍ‌ګانې د مارانو په شان وې چې په خپلو سرونو باندې یې خلک ټپي کول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_19.mp3', '', 1761754199, 1761754199),
(36946, 'Revelation 9:20', 'Revelation', 9, 20, 'پاتې انسانان چې د دې بلاګانو په وسیله نه وو وژل شوي، د خپلو عملونو نه توبه ونه ویستله او هغوی د پېریانو او بتانو د عبادت څخه لاس وانخیست چې د سرو زرو، سپینو زرو، برنجو، تیږو او لرګیو څخه جوړ شوي وو او نه یې شو کولای وویني، واوري او وګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_20.mp3', '', 1761754199, 1761754199),
(36947, 'Revelation 9:21', 'Revelation', 9, 21, 'همدارنګه هغوی د قتل، جادوګرۍ، زناکارۍ او غلا نه توبه ونه ویستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation9_verse_21.mp3', '', 1761754199, 1761754199),
(36948, 'Hebrews 12:1', 'Hebrews', 12, 1, 'نو اوس چې د شاهدانو دومره لویه ګڼه‌ګوڼه زمونږ څخه راچاپېره ده، نو راځئ چې هر اضافي بار یعنې هره ګناه چې په اسانۍ سره مو راګېروي، د خپل ځان نه لېرې کړو او په صبر او زغم سره په هغې سیالۍ کې منډه ووهو چې زمونږ په وړاندې پرته ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_1.mp3', '', 1761754199, 1761754199),
(36949, 'Hebrews 12:2', 'Hebrews', 12, 2, 'خپلې سترګې د عیسی یعنې زمونږ د ایمان د بنیاد ایښودونکي او کامل کوونکي خواته ونیسو. هغه په صلیب باندې د مړ کېدلو شرم وزغملو خو شرم یې مهم ونه ګڼلو، ځکه چې په دې پوهېده چې په دې کار سره به هغه په راتلونکې کې خوشحاله وي او اوس هغه د خدای د تخت ښي لاس ته ناست دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_2.mp3', '', 1761754199, 1761754199),
(36950, 'Hebrews 12:3', 'Hebrews', 12, 3, 'د هغه په هکله فکر وکړئ چې د ګناهکارانو له خوا د څومره مخالفتونو سره مخ شو، نو خپله حوصله له لاسه مه ورکوئ او بې‌زړه کېږئ مه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_3.mp3', '', 1761754199, 1761754199),
(36951, 'Hebrews 12:4', 'Hebrews', 12, 4, 'تاسو لا تر‌اوسه د ګناه په خلاف جنګ کې تر دې حده نه یئ رسېدلي چې وینه مو په کې تویه شوې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_4.mp3', '', 1761754199, 1761754199),
(36952, 'Hebrews 12:5', 'Hebrews', 12, 5, 'ایا تاسو دا هېر کړي دي چې خدای درته لکه د خپلو اولادونو په شان نصیحت کوي: ای زما زویه! کله چې تا اصلاح کوي څښتن نو هغه مه ګڼه سپک او کله چې هغه رټي تا، نو نا‌امیده کېږه مه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_5.mp3', '', 1761754199, 1761754199),
(36953, 'Hebrews 12:6', 'Hebrews', 12, 6, 'ځکه څښتن چې کوي مینه د کوم چا سره نو اصلاح کوي هغه او هغه چاته ورکوي سزا چې قبلوي یې د خپل زوی په توګه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_6.mp3', '', 1761754199, 1761754199),
(36954, 'Hebrews 12:7', 'Hebrews', 12, 7, 'تاسو اصلاح وزغمئ، ځکه چې دا زغم دا ښایي چې خدای تاسو سره د خپلو اولادونو په شان چلند کوي. ایا تاسو کله داسې اولاد لیدلی دی چې د خپل پلار له خوا اصلاح شوی نه وي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_7.mp3', '', 1761754199, 1761754199),
(36955, 'Hebrews 12:8', 'Hebrews', 12, 8, 'که چېرې تاسو د هغه د نورو اولادونو په شان اصلاح نه شئ، نو دا په دې معنی ده چې تاسو د هغه رښتیني اولادونه نه یئ، بلکې حرامیان یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_8.mp3', '', 1761754199, 1761754199),
(36956, 'Hebrews 12:9', 'Hebrews', 12, 9, 'برسېره پر‌دې، مونږ ټولو پلرونه درلودل چې مونږ یې اصلاح کولو او مونږ د هغوی درناوی کاوه. نو مونږ به د دې نه څومره زیاته د هغه چا تابعداري وکړو چې زمونږ روحاني پلار دی او مونږ ته ژوند راکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_9.mp3', '', 1761754199, 1761754199),
(36957, 'Hebrews 12:10', 'Hebrews', 12, 10, 'زمونږ دنیاوي پلرونه لکه څنګه چې هغوی ته ښه ښکاري، مونږ اصلاح کړي یو، خو د خدای اصلاح زمونږ د ښېګڼې دپاره ده، ترڅو مونږ د هغه په پاکوالي کې شریک شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_10.mp3', '', 1761754199, 1761754199),
(36958, 'Hebrews 12:11', 'Hebrews', 12, 11, 'هره اصلاح په خپل وخت کې خوشحالوونکې او خوندوره نه وي بلکې دردناکه وي، خو وروسته بیا د هغو خلکو دپاره چې په دې ډول روزل شوي دي، د یو رښتیني ژوند د ارامۍ یوه مېوه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_11.mp3', '', 1761754199, 1761754199),
(36959, 'Hebrews 12:12', 'Hebrews', 12, 12, 'نو له دې امله خپل ناتوانه لاسونه او کمزورې پښې قوي کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_12.mp3', '', 1761754199, 1761754199),
(36960, 'Hebrews 12:13', 'Hebrews', 12, 13, 'د خپلو قدمونو دپاره لاره سمه کړئ، ترڅو په تاسو کې د ځینو ګوډې پښې کمزورې او ناتوانه نه شي بلکې روغې شي. لارښوونې او خبردارۍ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_13.mp3', '', 1761754199, 1761754199),
(36961, 'Hebrews 12:14', 'Hebrews', 12, 14, 'کوښښ وکړئ چې د هرچا سره په سوله او سلامتۍ کې ژوند وکړئ او پاک او سپېڅلي اوسئ، ځکه چې د هغه پرته به هېڅوک څښتن ونه ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_14.mp3', '', 1761754199, 1761754199),
(36962, 'Hebrews 12:15', 'Hebrews', 12, 15, 'پام کوئ، هسې نه چې په تاسو کې څوک د خدای د فضل نه بې‌برخې شي او ستاسو په منځ کې کوم څوک ترخې او زهرجنې ریښې وځغلوي چې د تکلیف سبب شي او د هغه له امله ډېر خلک فاسد شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_15.mp3', '', 1761754199, 1761754199),
(36963, 'Hebrews 12:16', 'Hebrews', 12, 16, 'او ګورئ چې په تاسو کې دې څوک زناکار یا د عیسو په شان بې‌دینه نه شي چې د یوې مړۍ ډوډۍ دپاره یې د خپل مشرتوب حق خرڅ کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_16.mp3', '', 1761754199, 1761754199),
(36964, 'Hebrews 12:17', 'Hebrews', 12, 17, 'نو تاسو پوهېږئ سره له دې چې وروسته هغه غوښتل چې د برکت میراث تر‌لاسه کړي، خو هغه رد شو، ځکه چې د هغه دپاره د توبې ویستلو موقعه پیدا نه شوه، که څه هم هغه د اوښکو په تویولو سره د هغه برکت په لټه کې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_17.mp3', '', 1761754199, 1761754199),
(36965, 'Hebrews 12:18', 'Hebrews', 12, 18, 'تاسو لکه د اسراییلو د خلکو په شان د موسی په وخت کې د سینا غره ته چې د اور لمبې، سخته تیاره او توفان ؤ، راغلي نه یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_18.mp3', '', 1761754199, 1761754199),
(36966, 'Hebrews 12:19', 'Hebrews', 12, 19, 'کله چې خلکو د سرني او یو ډېر وېروونکی اواز واورېد، نو زارۍ یې وکړې چې خدای دې نور زمونږ سره خبرې ونه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_19.mp3', '', 1761754199, 1761754199),
(36967, 'Hebrews 12:20', 'Hebrews', 12, 20, 'ځکه چې هغوی د خدای دا حکم ونه شو زغملی چې وایي: «که چېرې یو حیوان هم په دې غره باندې پښه کېږدي، نو هغه باید سنګسار شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_20.mp3', '', 1761754199, 1761754199),
(36968, 'Hebrews 12:21', 'Hebrews', 12, 21, 'هغه منظره دومره وېروونکې وه چې موسی وویل: «زه د وېرې نه رپېږم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_21.mp3', '', 1761754199, 1761754199),
(36969, 'Hebrews 12:22', 'Hebrews', 12, 22, 'خو تاسو د صهیون غره او د ژوندي خدای ښار یعنې اسماني اورشلیم ته چې بې‌شمېره فرښتې په کې خوشحالي کوي، راغلي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_22.mp3', '', 1761754199, 1761754199),
(36970, 'Hebrews 12:23', 'Hebrews', 12, 23, 'تاسو د خدای د لومړني زېږول شویو اولادونو غونډې ته چې نومونه یې په جنت کې لیکل شوي دي، راغلي یئ. تاسو خدای ته چې د ټولو قاضي دی او د نېکانو روحونو ته چې کامل شوي دي، راغلي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_23.mp3', '', 1761754199, 1761754199),
(36971, 'Hebrews 12:24', 'Hebrews', 12, 24, 'تاسو عیسی ته چې د خدای او خلکو ترمنځ د نوي لوظ منځګړی دی او د هغه وینه د هابیل د وینې نه ډېر ښه پیغام ورکوي، راغلي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_24.mp3', '', 1761754199, 1761754199),
(36972, 'Hebrews 12:25', 'Hebrews', 12, 25, 'نو پام کوئ چې د هغه چا نه انکار ونه کړئ چې تاسو ته خبرې کوي. کله چې خلکو د هغه د اطاعت کولو نه انکار وکړ چې د ځمکې نه یې هغوی ته خبرې کولې او تېښته یې ونه کړه، نو که تاسو د هغه چا نه انکار وکړئ چې د اسمان نه ستاسو سره خبرې کوي، نو فکر کوئ چې تاسو به وکولای شئ وتښتئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_25.mp3', '', 1761754199, 1761754199),
(36973, 'Hebrews 12:26', 'Hebrews', 12, 26, 'په هغه وخت کې د خدای اواز ځمکه ولړزوله، خو اوس هغه وعده کړې ده: «یوځل بیا به زه یوازې ځمکه نه بلکې اسمان هم ولړزوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_26.mp3', '', 1761754199, 1761754199),
(36974, 'Hebrews 12:27', 'Hebrews', 12, 27, 'د هغه دا خبره یعنې «یوځل بیا» دې ته اشاره کوي چې هغه شیان چې خلق شوي دي هغه به ولړزول شي، ترڅو نه لړزېدونکي شیان پاتې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_27.mp3', '', 1761754199, 1761754199),
(36975, 'Hebrews 12:28', 'Hebrews', 12, 28, 'نو راځئ چې د هغې نه لړزېدونکې پاچاهۍ په خاطر چې خدای یې مونږ ته راکوي، شکرګزاري وکړو او په درناوي او وېرې سره داسې عبادت وکړو چې هغه ته د منلو وړ وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_28.mp3', '', 1761754199, 1761754199),
(36976, 'Hebrews 12:29', 'Hebrews', 12, 29, 'ځکه چې زمونږ خدای تباه کوونکی اور دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews12_verse_29.mp3', '', 1761754199, 1761754199),
(36977, 'Matthew 5:1', 'Matthew', 5, 1, 'کله چې عیسی د خلکو ګڼه‌ګوڼه ولیدله، نو غره ته وخوت او هلته کښېناست. شاګردان یې ورته راغلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_1.mp3', '', 1761754199, 1761754199),
