(36980, 'Matthew 5:4', 'Matthew', 5, 4, 'بختور دي هغه خلک چې اوس غمجن دي، ځکه چې هغوی به تسلي ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_4.mp3', '', 1761754199, 1761754199),
(36981, 'Matthew 5:5', 'Matthew', 5, 5, 'بختور دي هغه خلک چې عاجزان دي، ځکه چې هغوی به د ځمکې وارثان شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_5.mp3', '', 1761754199, 1761754199),
(36982, 'Matthew 5:6', 'Matthew', 5, 6, 'بختور دي هغه خلک چې د عدالت وږي تږي دي، ځکه چې هغوی به ماړه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_6.mp3', '', 1761754199, 1761754199),
(36983, 'Matthew 5:7', 'Matthew', 5, 7, 'بختور دي هغه خلک چې په نورو باندې رحم کوي، ځکه چې په هغوی به رحم وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_7.mp3', '', 1761754199, 1761754199),
(36984, 'Matthew 5:8', 'Matthew', 5, 8, 'بختور دي هغه خلک چې زړونه یې پاک دي، ځکه چې هغوی به خدای وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_8.mp3', '', 1761754199, 1761754199),
