(36986, 'Matthew 5:10', 'Matthew', 5, 10, 'بختور دي هغه خلک چې د عدالت په خاطر ځورول کیږي، ځکه چې اسماني پاچاهي د هغوی ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_10.mp3', '', 1761754199, 1761754199),
(36987, 'Matthew 5:11', 'Matthew', 5, 11, 'بختور یئ تاسو چې زما په خاطر خلک درته ښکنځل کوي، ځوروي مو او ستاسو په هکله داسې بدې خبرې کوي چې هغه دروغ وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_11.mp3', '', 1761754199, 1761754199),
(36988, 'Matthew 5:12', 'Matthew', 5, 12, 'خوښ او خوشحاله اوسئ، ځکه چې په اسمان کې ستاسو دپاره لوی اجر دی. ستاسو څخه مخکې هم هغوی په همدې ډول پیغمبران ځورولي وو. تاسو د دې دنیا مالګه او رڼا یئ (مرقوس ۹‏:‌۵۰ او لوقا ۱۴‏:‌۳۴‌‏-‌۳۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_12.mp3', '', 1761754199, 1761754199),
(36989, 'Matthew 5:13', 'Matthew', 5, 13, 'تاسو د نړۍ دپاره مالګه یئ، خو که مالګه خپل خوند له لاسه ورکړي، نو هغه به څنګه بېرته خپل خوند پیدا کړي؟ د هغې څخه نور هېڅ کار نه اخیستل کیږي، بې له دې چې لېرې وغورځول شي او خلک یې تر‌پښو لاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_13.mp3', '', 1761754199, 1761754199),
(36990, 'Matthew 5:14', 'Matthew', 5, 14, 'تاسو د نړۍ دپاره رڼا یئ. کوم ښار چې په غره باندې جوړ شوی وي هغه پټېدلی نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_14.mp3', '', 1761754199, 1761754199),
(36991, 'Matthew 5:15', 'Matthew', 5, 15, 'هېڅوک څراغ د دې دپاره نه بلوي چې هغه د کوم لوښي لاندې کېږدي چې پټ شي، بلکې هغه په څراغدان باندې ږدي چې د کور ټولو خلکو ته رڼا ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_15.mp3', '', 1761754199, 1761754199),
(36992, 'Matthew 5:16', 'Matthew', 5, 16, 'پرېږده چې ستاسو رڼا په خلکو باندې همداسې وځلیږي، ترڅو ستاسو نېک کارونه وویني او ستاسو پلار ته چې په اسمان کې دی جلال ورکړي. د شریعت په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_16.mp3', '', 1761754199, 1761754199),
(36993, 'Matthew 5:17', 'Matthew', 5, 17, 'داسې فکر مه کوئ چې زه د دې دپاره راغلی یم چې شریعت او د پیغمبرانو لیکنې منسوخ کړم. د هغو د منسوخ کولو دپاره نه یم راغلی بلکې د هغو د پوره کولو دپاره راغلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_17.mp3', '', 1761754199, 1761754199),
(36994, 'Matthew 5:18', 'Matthew', 5, 18, 'په یقین سره زه تاسو ته دا وایم ترڅو پورې چې ځمکه او اسمان موجود وي، نو د شریعت یو ډېر وړوکی ټکی به هم له منځه لاړ نه شي، ترڅو دا هرڅه سرته ونه رسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_18.mp3', '', 1761754199, 1761754199),
(36995, 'Matthew 5:19', 'Matthew', 5, 19, 'که چېرې څوک د دې حکمونو څخه یو ډېر وړوکی حکم هم مات کړي او نورو ته هم تعلیم ورکړي چې همداسې وکړي، نو په اسماني پاچاهۍ کې به ډېر کوچنی مقام ولري، خو څوک چې په هغو حکمونو باندې عمل وکړي او نورو ته هم تعلیم ورکړي چې همداسې وکړي، نو هغه به په اسماني پاچاهۍ کې لوړ مقام ولري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_19.mp3', '', 1761754199, 1761754199),
(36996, 'Matthew 5:20', 'Matthew', 5, 20, 'زه تاسو ته دا وایم تر هغې پورې چې ستاسو عدالت د فریسیانو او د شریعت د عالمانو د عدالت څخه بهتر نه وي، نو هېڅکله به په اسماني پاچاهۍ کې وردننه نه شئ. د قهر په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_20.mp3', '', 1761754199, 1761754199),
(36997, 'Matthew 5:21', 'Matthew', 5, 21, 'تاسو اورېدلي دي چې زمونږ نیکونو ته ویل شوي وو: ‹قتل مه کوئ.› که څوک قتل وکړي، نو هغه به تر محاکمې لاندې نیول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_21.mp3', '', 1761754199, 1761754199),
(36998, 'Matthew 5:22', 'Matthew', 5, 22, 'خو زه تاسو ته وایم چې که چېرې څوک خپل ورور باندې په قهر شي، نو هغه به محاکمه کیږي. که څوک خپل ورور ته سپکاوی وکړي، نو هغه به شورا ته د محاکمې دپاره بیول کیږي. که هغه ورته ووایي چې ته کم‌عقل یې، نو هغه به د دوزخ د اور لایق وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_22.mp3', '', 1761754199, 1761754199),
(36999, 'Matthew 5:23', 'Matthew', 5, 23, 'که چېرې ته د قربانۍ ځای ته کوم نذر راوړې او هلته در په یاد شي چې ورور دې درڅخه خفه دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_23.mp3', '', 1761754199, 1761754199),
(37000, 'Matthew 5:24', 'Matthew', 5, 24, 'نو خپل نذر دې د قربانۍ په ځای کې پرېږده او لاړ شه لومړی خپل ورور پخلا کړه او بیا راشه او خپل نذر دې وړاندې کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_24.mp3', '', 1761754199, 1761754199),
(37001, 'Matthew 5:25', 'Matthew', 5, 25, 'کله چې د خپل مدعي سره محکمې ته روان یې، نو په لاره کې ورسره روغه جوړه وکړه، هسې نه چې هغه دې قاضي ته په لاس ورکړي او قاضي به دې پولیس ته وسپاري او ته به په زندان کې واچول شې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_25.mp3', '', 1761754199, 1761754199),
(37002, 'Matthew 5:26', 'Matthew', 5, 26, 'په یقین سره زه تاسو ته دا وایم چې تر هغې به خلاص نه شې ترڅو پورې چې دې د خپل جېب وروستنۍ روپۍ نه وي ورکړې. د زنا نه کولو په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_26.mp3', '', 1761754199, 1761754199),
(37003, 'Matthew 5:27', 'Matthew', 5, 27, 'تاسو اورېدلي دي چې داسې ویل شوي دي: ‹زنا مه کوئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_27.mp3', '', 1761754199, 1761754199),
(37004, 'Matthew 5:28', 'Matthew', 5, 28, 'خو تاسو ته وایم چې که یو سړی کومې ښځې ته په بد نیت وګوري، نو په زړه کې یې د هغې سره زنا کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_28.mp3', '', 1761754199, 1761754199),
(37005, 'Matthew 5:29', 'Matthew', 5, 29, 'که چېرې ستا ښي سترګه ستا د ګناه سبب شي، نو هغه وباسه او لېرې یې وغورځوه. ځکه چې ستا دپاره به دا ښه وي چې د خپل بدن یو غړی له لاسه ورکړې، نه دا چې ټول بدن دې دوزخ ته وغورځول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_29.mp3', '', 1761754199, 1761754199),
(37006, 'Matthew 5:30', 'Matthew', 5, 30, 'که چېرې ستا ښي لاس ستا د ګناه سبب شي، نو هغه پرې کړه او لېرې یې وغورځوه، ځکه چې ستا دپاره به دا ښه وي چې د خپل بدن یو اندام له لاسه ورکړې، نه دا چې ټول بدن دې دوزخ ته لاړ شي. د طلاق په هکله تعلیم (متي ۱۹‏:‌۹ او مرقوس ۱۰‏:‌۱۱‌‏-‌۱۲ او لوقا ۱۶‏:‌۱۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_30.mp3', '', 1761754199, 1761754199),
(37007, 'Matthew 5:31', 'Matthew', 5, 31, 'همدارنګه ویل شوي دي: ‹کله چې څوک خپلې ښځې ته طلاق ورکوي، نو باید هغې ته طلاق‌نامه ورکړي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_31.mp3', '', 1761754199, 1761754199),
(37008, 'Matthew 5:32', 'Matthew', 5, 32, 'خو زه تاسو ته وایم چې که څوک خپله ښځه د زنا کولو نه پرته په کوم بل دلیل طلاقه کړي، نو د هغې څخه زنا کاره جوړوي او هرڅوک چې د داسې ښځې سره واده وکړي، نو هغه زنا کوي. د قسم خوړلو په هکله تعلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_32.mp3', '', 1761754199, 1761754199),
(37009, 'Matthew 5:33', 'Matthew', 5, 33, 'همدارنګه تاسو اورېدلي دي چې په پخوا زمانه کې خلکو ته ویل شوي وو: ‹خپل قسم مه ماتوئ، خو د څښتن په نوم مو چې کوم قسم خوړلی دی هغه سرته ورسوئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_33.mp3', '', 1761754199, 1761754199),
(37010, 'Matthew 5:34', 'Matthew', 5, 34, 'خو زه تاسو ته وایم چې هېڅکله قسم مه خورئ، نه په اسمان ځکه چې هغه د خدای تخت دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_34.mp3', '', 1761754199, 1761754199);